"use client"

import { cn } from "cn"
import { Bar, BarChart, CartesianGrid, Cell, XAxis, YAxis } from "recharts"

import {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
  type ChartConfig,
} from "@/components/ui/chart"

const chartConfig = {
  increase: { label: "Increase", color: "var(--chart-2)" },
  decrease: { label: "Decrease", color: "var(--destructive)" },
  total: { label: "Total", color: "var(--chart-1)" },
} satisfies ChartConfig

/**
 * Waterfall on the shadcn chart primitives: a transparent stacked base bar
 * carries each step to its running total; totals start from zero.
 */
function ChartWaterfall({
  steps,
  axes = true,
  legend = true,
  tooltip = true,
  className,
}: {
  steps: { label: string; value: number; total?: boolean }[]
  axes?: boolean
  legend?: boolean
  tooltip?: boolean
  className?: string
}) {
  let running = 0
  const rows = steps.map((s) => {
    if (s.total) {
      running = s.value
      return { label: s.label, base: 0, delta: s.value, kind: "total" as const }
    }
    const start = running
    running += s.value
    return { label: s.label, base: Math.min(start, running), delta: Math.abs(s.value), kind: s.value >= 0 ? ("increase" as const) : ("decrease" as const) }
  })
  return (
    <figure data-slot="chart" data-chart="waterfall" className={cn("flex w-full flex-col gap-2", className)}>
    <ChartContainer config={chartConfig}>
      <BarChart accessibilityLayer data={rows} margin={{ left: 12, right: 12 }}>
        {axes && <CartesianGrid vertical={false} />}
        {axes && <XAxis dataKey="label" tickLine={false} axisLine={false} tickMargin={8} />}
        {axes && <YAxis tickLine={false} axisLine={false} tickMargin={8} width={40} />}
        {tooltip && <ChartTooltip cursor={false} content={<ChartTooltipContent hideLabel={false} />} />}
        <Bar dataKey="base" stackId="w" fill="transparent" isAnimationActive={false} legendType="none" />
        <Bar dataKey="delta" stackId="w" radius={4}>
          {rows.map((r, i) => (
            <Cell key={i} fill={`var(--color-${r.kind})`} />
          ))}
        </Bar>
      </BarChart>
    </ChartContainer>
    {legend && (
      <figcaption className="flex flex-wrap justify-center gap-4 text-xs text-muted-foreground">
        {(Object.keys(chartConfig) as (keyof typeof chartConfig)[]).map((k) => (
          <span key={k} className="flex items-center gap-1.5">
            <span aria-hidden="true" className="size-2 rounded-xs" style={{ background: chartConfig[k].color }} />
            {chartConfig[k].label}
          </span>
        ))}
      </figcaption>
    )}
    </figure>
  )
}

export { ChartWaterfall }
